import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m.group(1),int(m.group(2)),int(m.group(3))
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G['Demo pair 1 output'])

def f(inp):
    h,w=len(inp),len(inp[0])
    o=[r[:] for r in inp]
    def mark(r,c): o[r][c]=3
    a=[(r,c) for r in range(h) for c in range(w) if inp[r][c]==2][0]
    b=[(r,c) for r in range(h) for c in range(w) if inp[r][c]==1][0]
    (sr,sc),(tr,tc)=a,b
    sgn_r=(tr>sr)-(tr<sr); sgn_c=(tc>sc)-(tc<sc)
    mark(sr+sgn_r,sc+sgn_c); sr+=sgn_r; sc+=sgn_c
    while True:
        dr,dc=tr-sr,tc-sc
        if abs(dr)<=abs(dc): step=(0,sgn_c)
        else: step=(sgn_r,0)
        np=(sr+step[0],sc+step[1])
        if abs(np[0]-tr)<=1 and abs(np[1]-tc)<=1: break
        mark(*np); sr+=step[0]; sc+=step[1]
    return o
